record.field:
{
  "type": "object",
  "properties": {
    "product": {"type": "string", "description": "Mã sản phẩm (VD: FPD3-01) hoặc tên sản phẩm"}
  },
  "required": ["product"]
}

{
  "type": "object",
  "properties": {
    "name": {"type": "string", "description": "Tên hoặc mã sản phẩm cần tìm trong Odoo"}
  },
  "required": ["name"]
}

{
  "type": "object",
  "properties": {
    "partner_id": {"type": "integer", "description": "ID khách hàng (res.partner)"},
    "products": {"type": "string", "description": "JSON array: [{\"name\": \"Tên SP\", \"quantity\": 1, \"price_unit\": 0}]"},
    "note": {"type": "string", "description": "Ghi chú cho báo giá (tùy chọn)"}
  },
  "required": ["partner_id", "products"]
}

{
  "type": "object",
  "properties": {
    "conversation_id": {"type": "integer", "description": "ID hội thoại Zalo (zalo.chat.conversation)"},
    "message": {"type": "string", "description": "Nội dung tin nhắn gửi cho khách"}
  },
  "required": ["conversation_id", "message"]
}
